import{_ as a,a0 as l,w as p,s as r,I as i,x as t,a1 as n,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Linux 中快速监控多个主机 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中快速监控多个主机 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中快速监控多个主机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中快速监控多个主机 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux","title":"如何在 Linux 中快速监控多个主机","tag":"201805","desc":""},"relativePath":"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux.md","filePath":"[post].md"}'),h={name:"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux.md"};function u(c,s,g,k,b,w){const e=l("Link");return p(),r("div",null,[s[16]||(s[16]=i("h1",{id:"如何在-linux-中快速监控多个主机",tabindex:"-1"},[t("如何在 Linux 中快速监控多个主机 "),i("a",{class:"header-anchor",href:"#如何在-linux-中快速监控多个主机","aria-label":"Permalink to “如何在 Linux 中快速监控多个主机”"},"​")],-1)),s[17]||(s[17]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/03/rwho-1-720x340.png",alt:""})],-1)),i("p",null,[s[1]||(s[1]=t("有很多监控工具可用来监控本地和远程 Linux 系统，一个很好的例子是 ",-1)),n(e,{href:"https://www.ostechnix.com/cockpit-monitor-administer-linux-servers-via-web-browser/"},{default:o(()=>[...s[0]||(s[0]=[t("Cockpit",-1)])]),_:1}),s[2]||(s[2]=t("。但是，这些工具的安装和使用比较复杂，至少对于新手管理员来说是这样。新手管理员可能需要花一些时间来弄清楚如何配置这些工具来监视系统。如果你想要以快速且粗略地在局域网中一次监控多台主机，你可能需要了解一下 “rwho” 工具。只要安装了 rwho 实用程序，它将立即快速地监控本地和远程系统。你什么都不用配置！你所要做的就是在要监视的系统上安装 “rwho” 工具。",-1))]),s[18]||(s[18]=d(`<p>请不要将 rwho 视为功能丰富且完整的监控工具。这只是一个简单的工具，它只监视远程系统的“正常运行时间”（<code>uptime</code>），“负载”（<code>load</code>）和<strong>登录的用户</strong>。使用 “rwho” 使用程序，我们可以发现谁在哪台计算机上登录；一个被监视的计算机的列表，列出了正常运行时间（自上次重新启动以来的时间）；有多少用户登录了；以及在过去的 1、5、15 分钟的平均负载。不多不少！而且，它只监视同一子网中的系统。因此，它非常适合小型和家庭办公网络。</p><h3 id="在-linux-中监控多台主机" tabindex="-1">在 Linux 中监控多台主机 <a class="header-anchor" href="#在-linux-中监控多台主机" aria-label="Permalink to “在 Linux 中监控多台主机”">​</a></h3><p>让我来解释一下 <code>rwho</code> 是如何工作的。每个在网络上使用 <code>rwho</code> 的系统都将广播关于它自己的信息，其他计算机可以使用 <code>rwhod</code> 守护进程来访问这些信息。因此，网络上的每台计算机都必须安装 <code>rwho</code>。此外，为了分发或访问其他主机的信息，必须允许 <code>rwho</code> 端口（例如端口 <code>513/UDP</code>）通过防火墙/路由器。</p><p>好的，让我们来安装它。</p><p>我在 Ubuntu 16.04 LTS 服务器上进行了测试，<code>rwho</code> 在默认仓库中可用，所以，我们可以使用像下面这样的 APT 软件包管理器来安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install rwho</span></span></code></pre></div><p>在基于 RPM 的系统如 CentOS、 Fedora、 RHEL 上，使用以下命令来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install rwho</span></span></code></pre></div><p>如果你在防火墙/路由器之后，确保你已经允许使用 rwhod 513 端口。另外，使用命令验证 <code>rwhod</code> 守护进程是否正在运行：</p><p>$ sudo systemctl status rwhod</p><p>如果它尚未启动，运行以下命令启用并启动 <code>rwhod</code> 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rwhod</span></span>
<span class="line"><span>$ sudo systemctl start rwhod</span></span></code></pre></div><p>现在是时候来监视系统了。运行以下命令以发现谁在哪台计算机上登录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rwho</span></span>
<span class="line"><span>ostechni ostechnix:pts/5 Mar 12 17:41</span></span>
<span class="line"><span>root server:pts/0 Mar 12 17:42</span></span></code></pre></div><p>正如你所看到的，目前我的局域网中有两个系统。本地系统用户是 <code>ostechnix</code> （Ubuntu 16.04 LTS），远程系统的用户是 <code>root</code> （CentOS 7）。可能你已经猜到了，<code>rwho</code> 与 <code>who</code> 命令相似，但它会监视远程系统。</p><p>而且，我们可以使用以下命令找到网络上所有正在运行的系统的正常运行时间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ruptime</span></span>
<span class="line"><span>ostechnix up 2:17, 1 user, load 0.09, 0.03, 0.01</span></span>
<span class="line"><span>server up 1:54, 1 user, load 0.00, 0.01, 0.05</span></span></code></pre></div><p>这里，<code>ruptime</code>（类似于 <code>uptime</code> 命令）显示了我的 Ubuntu（本地） 和 CentOS（远程）系统的总运行时间。明白了吗？棒极了！以下是我的 Ubuntu 16.04 LTS 系统的示例屏幕截图：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/rwho.png" alt=""></p><p>你可以在以下位置找到有关局域网中所有其他机器的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /var/spool/rwho/</span></span>
<span class="line"><span>whod.ostechnix whod.server</span></span></code></pre></div><p>它很小，但却非常有用，可以发现谁在哪台计算机上登录，以及正常运行时间和系统负载详情。</p><p><strong>建议阅读：</strong></p><p>请注意，这种方法有一个严重的漏洞。由于有关每台计算机的信息都通过网络进行广播，因此该子网中的每个人都可能获得此信息。通常情况下可以，但另一方面，当有关网络的信息分发给非授权用户时，这可能是不必要的副作用。因此，强烈建议在受信任和受保护的局域网中使用它。</p><p>更多的信息，查找 man 手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man rwho</span></span></code></pre></div><p>好了，这就是全部了。更多好东西要来了，敬请期待！</p><p>干杯！</p><hr>`,29)),i("p",null,[s[4]||(s[4]=t("via: ",-1)),n(e,{href:"https://www.ostechnix.com/how-to-quickly-monitor-multiple-hosts-in-linux/"},{default:o(()=>[...s[3]||(s[3]=[t("https://www.ostechnix.com/how-to-quickly-monitor-multiple-hosts-in-linux/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=t("作者：",-1)),n(e,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...s[5]||(s[5]=[t("SK",-1)])]),_:1}),s[9]||(s[9]=t(" 译者：",-1)),n(e,{href:"https://github.com/MjSeven"},{default:o(()=>[...s[6]||(s[6]=[t("MjSeven",-1)])]),_:1}),s[10]||(s[10]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[7]||(s[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[11]||(s[11]=[t("LCTT",-1)])]),_:1}),s[14]||(s[14]=t(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[12]||(s[12]=[t("Linux中国",-1)])]),_:1}),s[15]||(s[15]=t(" 荣誉推出",-1))])])}const C=a(h,[["render",u]]);export{f as __pageData,C as default};
